content:
Replace `index.ts` with:

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const env = config.get("env") ?? pulumi.getStack();
const region = config.get("region") ?? "us-east-1";
const dbPassword = config.requireSecret("dbPassword");

if (env !== "dev" && env !== "prod") {
    throw new Error(`Unsupported environment "${env}"; expected "dev" or "prod".`);
}

const isProd = env === "prod";

const provider = new aws.Provider("aws-provider", {
    region: region as aws.Region,
});

const resourceOptions: pulumi.CustomResourceOptions = {
    provider,
};

// S3 bucket
const bucket = new aws.s3.Bucket("app-bucket", {
    bucket: `myapp-assets-${env}`,
    versioning: {
        enabled: true,
    },
    tags: {
        Environment: env,
        Project: "myapp",
    },
}, resourceOptions);

new aws.s3.BucketServerSideEncryptionConfigurationV2(
    "app-bucket-encryption",
    {
        bucket: bucket.id,
        rules: [{
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        }],
    },
    resourceOptions,
);

new aws.s3.BucketPublicAccessBlock("app-bucket-public-access-block", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
}, resourceOptions);

// Derive values from Outputs with apply/interpolate; never await an Output.
const bucketUrl: pulumi.Output<string> =
    pulumi.interpolate`https://${bucket.bucket}.s3.${region}.amazonaws.com`;

// RDS PostgreSQL
const db = new aws.rds.Instance("app-db", {
    identifier: `myapp-${env}`,
    instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    engineVersion: "16",
    allocatedStorage: 20,

    dbName: "appdb",
    username: "app_user",
    password: dbPassword,

    multiAz: isProd,
    storageEncrypted: true,
    publiclyAccessible: false,
    deletionProtection: true,
    backupRetentionPeriod: 7,

    skipFinalSnapshot: false,
    finalSnapshotIdentifier: `myapp-${env}-final`,
}, resourceOptions);

export const bucketEndpoint = bucketUrl;
export const dbEndpoint = db.endpoint;
```

Set the password as an encrypted Pulumi stack secret rather than storing it in source:

```bash
pulumi stack select dev
pulumi config set env dev
pulumi config set region us-east-1
pulumi config set --secret dbPassword 'replace-with-a-strong-password'

pulumi stack select prod
pulumi config set env prod
pulumi config set region us-east-1
pulumi config set --secret dbPassword 'replace-with-a-different-strong-password'
```

The key fixes are:

- `pulumi.Output` values are transformed with `pulumi.interpolate` or `.apply()`, not `await`.
- `config.requireSecret("dbPassword")` returns a secret `Output<string>` and keeps the password encrypted in stack configuration.
- `bucketEndpoint` is now an `Output<string>`, not a `Promise`.
- The bucket name—not its ARN—is used to construct the S3 URL.
- Bucket encryption/public-access blocking and the required RDS protection settings are enabled.
